{
{#- 
Last Updated by Diego Pino 2026-10-11 2026 for Digital Instantiations
Previously by Diego Pino 2026-02-11 2026 for LoD URLs
Previously Updated by Diego Pino 2026-30-10 2026 for Segments
Previously Updated by Diego Pino 2026-21-09 2026 for episodes
Previously updated by Dylan 2026-10-09, added additional type mappings
Oct 2026 by Diego Pino (WIP).
So far only Series. To be enriched with more fields as we start seeingcleaned up CSVs -#}
{% macro cortext_url_to_lod(url) %}
  {%- set parts = url|split('(') -%}
  {%- set id = parts[1]|default('')|trim(')') -%}
  {%- set authority = parts[0]|default('')|trim|lower %}
  {%- if authority in "library of congress name authority id" -%}
     {{- 'http://id.loc.gov/authorities/names/' ~ id -}}
  {%- elseif authority in "wikidata id" -%}
     {{- 'https://www.wikidata.org/wiki/' ~ id -}}
  {%- elseif authority in "associated press topic id" %}
     {{- 'urn:nypr:associated-press-subjects:' ~ id -}}
  {%- else -%}
   {{- url }} 
  {%- endif -%}  
{%- endmacro %}
{% set type_mapping = {
  "Shows" : "Series",
  "Subseries" : "Subseries",
  "Season" : "Season",
  "Episodes": "Episode",
  "Segment": "Segment",
  "DigitalInstantiation": "DigitalInstantiation"
  } %}
  {% set semantic_type = data.asset_type ?? data.type %}
  {# Fields we need from Segment based on Dylan Oct 30th 2026
  node_uuid,
  audios,
  corefield_asset_description, --> Different type so i can filter via twig
  corefield_notes, -->  Different type so i can filter via twig
  corefield_original_file_name, --> Local ID -> DigitalInstantiation
  dates_etdf, --> 
  label,
  nypr_audio_source --> DigitalInstantiation
  nypr_coding_history -> DigitalInstantiation
  nypr_contributor, --> ONLY USE OF PARENT IS EMPTY (so it is a local vocab)
  nypr_contributor_parent_record,
  nypr_external_identifier_type_and_identifier,
  nypr_loudness_range --> DigitalInstantiation
  nypr_loudness_value_(lufs) --> DigitalInstantiation
  nypr_max_momentary_loudness --> DigitalInstantiation
  nypr_max_short_term_loudness --> DigitalInstantiation
  nypr_max_true_peak_level --> DigitalInstantiation
  nypr_order_within_episode -> sequence_id -> Integer
  nypr_other_role,
  nypr_ownership,
  nypr_provenance -> Digital Instantiaton
  nypr_publish_status --> Reflect/snare

  nypr_topic_id_link,
  nypr_topic_id_link_parent_record,
  
  nypr_transcript,

  type,
  recordid -->
  asset_type,
  issegmentof,
  minimum_viable_metadata_present,
  
  hide_this_duplicate -> possible_duplicate = can lead to hiding 
  ... Things you know have duplicates but are been show, do not need this
  
  medium,
  publisher_lod,
  ownership,ismemberof 
 #}
  {% set real_type = type_mapping[semantic_type]|default(data.type|default("Collection")) %}
  "label": {{ data.label|json_encode|raw }},
  {%- if data.nypr_episode_title is defined and data.nypr_episode_title is not empty and real_type != "DigitalInstantiation" %}
  "label_alt" : {{ data.nypr_episode_title|json_encode|raw }},
  {% endif -%}
  {%- if data.corefield_title is defined and data.corefield_title is not empty and real_type == "DigitalInstantiation" %}
  "label_alt" : {{ data.corefield_title|json_encode|raw }},
  {% endif -%}
  "type": {{real_type|json_encode|raw }},
  {% set local_identifiers = [] %}
  {% if real_type != 'DigitalInstantiation' %}
    {% set local_identifiers = [{"source":"Cortex Record ID","value":data.recordid|default('Undefined')}] %}
  {% endif %}
  {% for local_id in data.nypr_external_identifier_type_and_identifier|default([]) %}
     {% set local_id_split = local_id|split('(') %}
     {% set skip = false %}
{# DigitalInstantiation exception. Do not include Paths of any type if not an actual Digital Instantiation #}
     {% if real_type != 'DigitalInstantiation' and "path" in local_id_split[0]|default('Undefined')|trim|lower %}
        {% set skip = true %}
{# DigitalInstantiation Inverse. Only include Paths of any type if an actual Digital Instantiation #}
	{% elseif real_type == 'DigitalInstantiation' and "path" not in local_id_split[0]|default('Undefined')|trim|lower %}
        {% set skip = true %}
     {% endif %}
     {% if not skip %}
       {% set local_identifiers = local_identifiers|merge([{"source": local_id_split[0]|default('Undefined')|trim, "value": local_id_split[1]|default('none')|trim(')')}]) %}
     {% endif %}
  {% endfor %}
  {% if real_type == "DigitalInstantiation" and data.corefield_original_file_name is not empty %}
    {% set local_identifiers = local_identifiers|merge([{"source": "filename", "value": data.corefield_original_file_name }]) %}
  {% endif %}
  "local_identifiers": {{ local_identifiers|json_encode|raw }},
  {%- if data.dates_etdf is defined and data.dates_etdf is not empty %}
  "dates_edtf" : {{ data.dates_etdf|json_encode|raw }},
  {% endif -%}
  {%- if data.corefield_notes is defined and data.corefield_notes is not empty -%}
  "notes": {{ data.corefield_notes|json_encode|raw }},
  {% endif -%}
  {%- set descriptions = [] -%}
  {%- if data.corefield_asset_description is defined and data.corefield_asset_description is not empty -%}
	{% set description_type = "Abstract" %}
    {% if data.corefield_asset_description|striptags|length != data.corefield_asset_description|length %}
    	{% set description_type = "AbstractNeedsReview" %}
    {% endif -%}
    {% set descriptions = descriptions|merge([{"description": data.corefield_asset_description|trim, "description_type": description_type}]) %}
  {% endif -%}
  {%- if data.nypr_transcript is defined and data.nypr_transcript is not empty -%}
	{% set description_type = "Transcript" %}
    {% if data.nypr_transcript|striptags|length != data.nypr_transcript|length %}
        {% set description_type = "TranscriptNeedsReview" %}
    {% endif -%}
    {% set descriptions = descriptions|merge([{"description": data.nypr_transcript|trim, "description_type": description_type}]) %}
  {% endif -%}
  {%- if data.nypr_short_description is defined and data.nypr_short_description is not empty -%}
	{% set description_type = "CMS Tease" %}
    {% if data.nypr_short_description|striptags|length != data.nypr_short_description|length %}
        {% set description_type = "TeaseNeedsReview" %}
    {% endif -%}
    {% set descriptions = descriptions|merge([{"description": data.nypr_short_description|trim, "description_type": description_type}]) %}
  {% endif -%}
  {% if descriptions is not empty %}
    "descriptions": {{ descriptions|json_encode|raw }},
  {% endif -%}
  {%- if data.corefield_usage_rights is defined and data.corefield_usage_rights is not empty -%}
  "rights": {{ data.corefield_usage_rights|json_encode|raw }},
  {% endif -%}
  {% set combined_role_parent_record = data.nypr_other_role_parent_record|default([])|merge(data.nypr_contributor_parent_record|default([])) %}
  {% if combined_role_parent_record is not empty and 
combined_role_parent_record is iterable
  %}
    {% set contributor_lod = [] %}
    {% set publisher_lod = [] %}
    {% set contributor_local = [] %}
    {% for grouped_contributor in combined_role_parent_record %}
		{% for url in grouped_contributor.urls|default([]) %}
           {% set url_lod = _self.cortext_url_to_lod(url) %}
           {% if "Produc" in grouped_contributor.type|default('') %}
             {% set publisher_lod = publisher_lod|merge([
             {
              "name_uri": url_lod,
              "name_label": grouped_contributor.label,
              "agent_type": null,
              "role_label": grouped_contributor.type,
              "role_uri": "http://pbcore.org/pbcore-controlled-vocabularies/creatorrole-and-contributorrole-vocabulary/#" ~ grouped_contributor.type
              }
          ]) %}
           {% else %}
             {% set contributor_lod = contributor_lod|merge([
             {
              "name_uri": url_lod,
              "name_label": grouped_contributor.label,
              "agent_type": null,
              "role_label": grouped_contributor.type,
              "role_uri": "http://pbcore.org/pbcore-controlled-vocabularies/creatorrole-and-contributorrole-vocabulary/#" ~ grouped_contributor.type
              }
          ]) %}
           {% endif %}
        {% endfor %}      
    {% endfor %}
	{% if contributor_lod is not empty %}
  "contributor_lod": {{ contributor_lod|json_encode|raw }}, 
	{% endif%}
    {% if publisher_lod is not empty %}
  "publisher_lod": {{ publisher_lod|json_encode|raw }}, 
	{% endif%}
  {% endif %}
  {% if data.nypr_lcsh_id_link_parent_record is not empty and 
data.nypr_lcsh_id_link_parent_record is iterable
  %}
    {% set subjects_loc = [] %}
    {% for subjects in data.nypr_lcsh_id_link_parent_record %}
		{% for url in subjects.urls|default([]) %}
           {% set url_lod = _self.cortext_url_to_lod(url) %}
           {% set subjects_loc = subjects_loc|merge([
             {
              "url": url_lod,
              "label": subjects.label,
              }
          ]) %}
        {% endfor %}      
    {% endfor %}
	{% if subjects_loc is not empty %}
  "subjects_loc": {{ subjects_loc|json_encode|raw }}, 
	{% endif%}
 {% endif%} 
  {% if data.nypr_topic_id_link_parent_record is not empty and 
data.nypr_topic_id_link_parent_record is iterable
  %}
    {% set subjects_ap = [] %}
    {% for topics in data.nypr_topic_id_link_parent_record %}
		{% for url in topics.urls|default([]) %}
           {% set url_lod = _self.cortext_url_to_lod(url) %}
           {% set subjects_ap = subjects_ap|merge([
             {
              "url": url_lod,
              "label": topics.label,
              }
          ]) %}
        {% endfor %}      
    {% endfor %}
	{% if subjects_ap is not empty %}
  "subjects_ap": {{ subjects_ap|json_encode|raw }}, 
	{% endif%}
 {% endif%}
  {% if data.nypr_lcnaf_id_link_parent_record is not empty and 
data.nypr_lcnaf_id_link_parent_record is iterable
  %}
    {% set subject_lcnaf_names = [] %}
    {% for places in data.nypr_lcnaf_id_link_parent_record %}
		{% for url in places.urls|default([]) %}
           {% set url_lod = _self.cortext_url_to_lod(url) %}
           {% set subject_lcnaf_names = subject_lcnaf_names|merge([
             {
              "url": url_lod,
              "label": places.label,
              }
          ]) %}
        {% endfor %}      
    {% endfor %}
	{% if subject_lcnaf_names is not empty %}
  "subject_lcnaf_names": {{ subject_lcnaf_names|json_encode|raw }}, 
	{% endif%}
 {% endif%}
  "source_system": {{ data.source_system|default("Cortex")|json_encode|raw }},
  "minimum_viable_metadata_present": {{ data.minimum_viable_metadata_present|default("No")|json_encode|raw }},
  {% if real_type != 'DigitalInstantiation' %}
  "publish_status": {{ data.nypr_publish_status|json_encode|raw }},
  "ownership": {{ data.nypr_ownership|json_encode|raw }},
  {% endif %}
  "medium": {{ data.medium is iterable ? data.medium|json_encode|raw : [data.medium]|json_encode|raw }},
  {% if data.hide_this_duplicate == 'Yes' %}
  "possible_duplicate": true,
  {% endif %}
  {% if data.nypr_order_within_episode is not empty %}
  "sequence_id": {{ (data.nypr_order_within_episode + 0)|json_encode|raw }},
  {% endif %}
  {#- Digital Instantiation specific 
  "annotations": [
        {
            "type": "Provenance",
            "value": "BWF created from Municipal Archives lacquer transcription disc. Reformatted as part of NEH project."
        },
        {
            "type": "Stylus_size",
            "value": "2.0 ET"
        },
        {
            "type": "LF_turnover",
            "value": "500 Hz"
        },
        {
            "type": "10kHz_att",
            "value": "8.5 dB"
        },
        {
            "value": "Outside start."
        }
    ],
    
    Using as type the same labels found in mediainfo for the same fields
     "loudnessvalue": "-23.95",
     "loudnessrange": "10.64",
     "maxtruepeaklevel": "-2.13",
     "maxmomentaryloudness": "-8.78",
     "maxshorttermloudness": "-14.13"
   -#}
  {% if real_type == 'DigitalInstantiation' %}
    {% set digital_instantiation_annotation = {} %}
    {% if data.nypr_provenance is not empty %}
      {% set digital_instantiation_annotation = digital_instantiation_annotation|merge([
         {
              "type": "Provenance",
              "value": data.nypr_provenance
          }])
      %}
    {% endif %}
    {% if data.nypr_loudness_range is not empty %}
      {% set digital_instantiation_annotation = digital_instantiation_annotation|merge([
         {
              "type": "loudnessrange",
              "value": data.nypr_loudness_range
          }])
      %}
    {% endif %}
    {% if data["nypr_loudness_value_(lufs]"] is not empty %}
      {% set digital_instantiation_annotation = digital_instantiation_annotation|merge([
         {
              "type": "loudnessvalue",
              "value": data["nypr_loudness_value_(lufs"]
          }])
      %}
    {% endif %}
    {% if data.nypr_max_momentary_loudness is not empty %}
      {% set digital_instantiation_annotation = digital_instantiation_annotation|merge([
         {
              "type": "maxmomentaryloudness",
              "value": data.nypr_max_momentary_loudness
          }])
      %}
    {% endif %}  
    {% if data.nypr_max_short_term_loudness is not empty %}
      {% set digital_instantiation_annotation = digital_instantiation_annotation|merge([
         {
              "type": "maxshorttermloudness",
              "value": data.nypr_max_short_term_loudness
          }])
      %}
    {% endif %}    
    {% if data.nypr_max_true_peak_level is not empty %}
      {% set digital_instantiation_annotation = digital_instantiation_annotation|merge([
         {
              "type": "maxtruepeaklevel",
              "value": data.nypr_max_true_peak_level
          }])
      %}
    {% endif %}
    {% if digital_instantiation_annotation is not empty %}
  "annotations": {{ digital_instantiation_annotation|json_encode|raw }},
    {% endif %}
  {% endif %}  
  "as:generator": {
        "type": "Create",
        "actor": {
            "url": {{ setURL|json_encode|raw }},
            "name": "ami",
            "type": "Service"
        },
        "endTime": "{{"now"|date("c")}}",
        "summary": "Generator",
        "@context": "https:\/\/www.w3.org\/ns\/activitystreams"
     }
}
